CREATE TABLE counterfactual_methodology_versions(id text PRIMARY KEY,organization_id text NOT NULL REFERENCES organizations(id),methodology_key text NOT NULL,version integer NOT NULL CHECK(version>0),name text NOT NULL,treasury_id text NOT NULL,policy_version_id text NOT NULL REFERENCES policy_versions(id),schema_version text NOT NULL CHECK(schema_version='treasury.counterfactual-methodology.v1'),content jsonb NOT NULL,content_hash text NOT NULL CHECK(content_hash~'^0x[0-9a-f]{64}$'),created_by text NOT NULL,counterfactual_result_available boolean NOT NULL DEFAULT false CHECK(counterfactual_result_available=false),net_benefit_calculated boolean NOT NULL DEFAULT false CHECK(net_benefit_calculated=false),causal_attribution_established boolean NOT NULL DEFAULT false CHECK(causal_attribution_established=false),onchain_dao_approval_observed boolean NOT NULL DEFAULT false CHECK(onchain_dao_approval_observed=false),advisory_only boolean NOT NULL DEFAULT true CHECK(advisory_only=true),asset_execution_authorized boolean NOT NULL DEFAULT false CHECK(asset_execution_authorized=false),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,methodology_key,version));
CREATE TABLE counterfactual_methodology_events(id text PRIMARY KEY,organization_id text NOT NULL REFERENCES organizations(id),methodology_version_id text NOT NULL REFERENCES counterfactual_methodology_versions(id),ordinal integer NOT NULL CHECK(ordinal>=0),status text NOT NULL CHECK(status IN('DRAFT','HUMAN_APPROVED','RETIRED')),actor_id text NOT NULL,rationale text NOT NULL,payload_hash text NOT NULL CHECK(payload_hash~'^0x[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(methodology_version_id,ordinal));
CREATE INDEX counterfactual_methodology_org_key_idx ON counterfactual_methodology_versions(organization_id,methodology_key,version DESC);CREATE INDEX counterfactual_methodology_event_idx ON counterfactual_methodology_events(organization_id,methodology_version_id,ordinal DESC);
CREATE OR REPLACE FUNCTION guard_counterfactual_methodology() RETURNS trigger AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM policy_versions p WHERE p.id=NEW.policy_version_id AND p.organization_id=NEW.organization_id)THEN RAISE EXCEPTION 'counterfactual methodology policy organization mismatch';END IF;RETURN NEW;END;$$ LANGUAGE plpgsql;CREATE TRIGGER counterfactual_methodology_lineage_guard BEFORE INSERT ON counterfactual_methodology_versions FOR EACH ROW EXECUTE FUNCTION guard_counterfactual_methodology();
CREATE OR REPLACE FUNCTION guard_counterfactual_methodology_event() RETURNS trigger AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM counterfactual_methodology_versions m WHERE m.id=NEW.methodology_version_id AND m.organization_id=NEW.organization_id)THEN RAISE EXCEPTION 'counterfactual methodology event organization mismatch';END IF;RETURN NEW;END;$$ LANGUAGE plpgsql;CREATE TRIGGER counterfactual_methodology_event_tenant_guard BEFORE INSERT ON counterfactual_methodology_events FOR EACH ROW EXECUTE FUNCTION guard_counterfactual_methodology_event();
CREATE OR REPLACE FUNCTION reject_counterfactual_methodology_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'counterfactual methodology records are immutable';END;$$ LANGUAGE plpgsql;CREATE TRIGGER counterfactual_methodology_version_immutable BEFORE UPDATE OR DELETE ON counterfactual_methodology_versions FOR EACH ROW EXECUTE FUNCTION reject_counterfactual_methodology_mutation();CREATE TRIGGER counterfactual_methodology_event_immutable BEFORE UPDATE OR DELETE ON counterfactual_methodology_events FOR EACH ROW EXECUTE FUNCTION reject_counterfactual_methodology_mutation();
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['counterfactual_methodology_versions','counterfactual_methodology_events']LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_organization_isolation ON %I USING(aeos_is_system_worker() OR organization_id=aeos_current_organization_id()) WITH CHECK(aeos_is_system_worker() OR organization_id=aeos_current_organization_id())',t);EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON %I TO aeos_app',t);END LOOP;END $$;
